previewCss:
.darma-loader-darma-b14-window-blinds { --accent: var(--loader-color, #64748b); --accent-2: var(--loader-secondary-color, #38bdf8); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .84); position: relative; display: flex; flex-direction: column; justify-content: space-between; padding: 5% 4%; border-radius: 4px; overflow: hidden; perspective: 420px; background: linear-gradient(color-mix(in srgb, #fff 58%, var(--accent-2)), color-mix(in srgb, #fff 18%, var(--accent-2))); }
.darma-loader-darma-b14-window-blinds span { height: 12%; border-radius: 2px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 24%, var(--accent))); animation: darma-loader-darma-b14-window-blinds-tilt-slat calc(var(--loader-speed, 1s) * 2.8) ease-in-out infinite; }
.darma-loader-darma-b14-window-blinds span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .07); }
.darma-loader-darma-b14-window-blinds span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .14); }
.darma-loader-darma-b14-window-blinds span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .21); }
.darma-loader-darma-b14-window-blinds span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * .28); }
.darma-loader-darma-b14-window-blinds span:nth-child(6) { animation-delay: calc(var(--loader-speed, 1s) * .35); }
.darma-loader-darma-b14-window-blinds::after { content: ''; position: absolute; z-index: 2; top: 0; right: 9%; width: 1.6%; height: 100%; background: color-mix(in srgb, #000 34%, var(--accent-2)); }
@keyframes darma-loader-darma-b14-window-blinds-tilt-slat { 0%, 12% { transform: rotateX(0deg); } 44%, 68% { transform: rotateX(74deg); } 92%, 100% { transform: rotateX(0deg); } }

